{
    return "Rebate Accrual Process";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METRebateAccrualController controller = new METRebateAccrualController();
    controller.parmArgs(_args);
    controller.initContract();
    controller.startOperation();
}

